#ifndef ZEPHYR_TESTS_SUBSYS_FS_FAT_FS_API_SRC_TEST_FAT_H_
#define ZEPHYR_TESTS_SUBSYS_FS_FAT_FS_API_SRC_TEST_FAT_H_

#include <zephyr/ztest.h>
#include <zephyr/fs/fs.h>
#include <zephyr/fs/fat_fs.h>
#include <ff.h> /* For FATFS_MNTP */

/*
 * Ensure one disk access type is selected.
 * Default to RAM disk if none is explicitly configured.
 */
#if !defined(CONFIG_DISK_ACCESS_RAM) && \
    !defined(CONFIG_DISK_ACCESS_FLASH) && \
    !defined(CONFIG_DISK_ACCESS_SDHC)
#define CONFIG_DISK_ACCESS_RAM 1
#endif

#if defined(CONFIG_DISK_ACCESS_RAM)
#define DISK_NAME "RAM"
#define DISK_MOUNT_PT "/RAM:"
#elif defined(CONFIG_DISK_ACCESS_FLASH)
#define DISK_NAME "NAND"
#define DISK_MOUNT_PT "/NAND:"
#elif defined(CONFIG_DISK_ACCESS_SDHC)
#define DISK_NAME "SD"
#define DISK_MOUNT_PT "/SD:"
#else
/* This should ideally not be reached if the above logic is correct */
#error "Failed to select DISK access type (fallback failed)"
#endif

/* Define the FATFS mount point if not already defined by ff.h or Kconfig */
#ifndef FATFS_MNTP
#define FATFS_MNTP DISK_MOUNT_PT
#endif

/*
 * Helper macros for filesystem operations to adapt to API changes
 * and simplify test code. These assume the test files use these wrappers.
 */

/* fs_open: int fs_open(struct fs_file_t *file, const char *path, fs_mode_t flags) */
#define TC_FS_OPEN(file_ptr, path_str, flags_val) \
	fs_open(file_ptr, path_str, flags_val)

/* fs_statvfs: int fs_statvfs(const char *path, struct fs_statvfs *stat) */
#define TC_FS_STATVFS(path_str, stat_ptr) \
	fs_statvfs(path_str, stat_ptr)

/* fs_rename: int fs_rename(const char *from, const char *to) */
#define TC_FS_RENAME(from_path_str, to_path_str) \
	fs_rename(from_path_str, to_path_str)

/* Common test functions declarations (implemented in common.c) */
void test_fat_mount(void);
void test_fat_unmount(void);
void test_fat_format(void);
void test_fat_setup(void);
void test_fat_teardown(void);

#endif /* ZEPHYR_TESTS_SUBSYS_FS_FAT_FS_API_SRC_TEST_FAT_H_ */
